-- ═══ Lo que dijo cada sitio (234 visitados, uno por empresa) ══════════════
--
-- Pedido del dueño: cruzar las cuentas con información web. Se hace visitando
-- el SITIO de cada una —el dominio ya salía de su correo corporativo— en vez
-- de buscar marca por marca: lo que devuelve el propio sitio no se puede
-- inventar, y una búsqueda mal leída sí.
--
-- De una sola petición sale todo lo que el módulo ya sabía guardar: si vive,
-- cuánto tarda, en qué plataforma está, si vende en línea y sus redes.
--
-- RESULTADO: 143 de 234 viven. 91 NO: el dominio del correo existe pero no
-- hospeda página. Eso no es un hueco, es un dato de venta — tienen dominio
-- propio y operan por WhatsApp y catálogo.
-- Plataformas: 75 a la medida, 33 Shopify, 23 WooCommerce, 5 Wix, 4 WordPress,
-- 3 PrestaShop. 72 con carrito y 71 con Instagram en el pie de página.
--
-- ⚠️ El patrón de Magento traía "mage/", que matchea dentro de "image/": daba
-- 56 Magento falsos. Corregido antes de escribir nada.

create temp table _web (id uuid, http int, seg numeric, carrito boolean,
  plataforma text, ig text, fb text, tt text, ctx text) on commit drop;

update abm_cuentas c set
  sitio_http = w.http, sitio_seg = w.seg, sitio_carrito = w.carrito,
  plataforma_web = coalesce(w.plataforma, c.plataforma_web),
  instagram = coalesce(c.instagram, w.ig),
  facebook  = coalesce(c.facebook,  w.fb),
  tiktok    = coalesce(c.tiktok,    w.tt),
  -- Lo que dice el sitio de sí mismo se suma al contexto, no lo pisa.
  contexto = case when w.ctx is null or w.ctx = '' then c.contexto
                  else coalesce(c.contexto || ' · ', '') || w.ctx end,
  updated_at = now()
from _web w where c.id = w.id;

-- ── El puntaje SE RECALCULA, no se deja como estaba ────────────────────────
-- La plataforma y el estado del sitio alimentan `dolor` en calcularPuntaje()
-- (lib/crm/abm.lib.ts): +16 si tiene e-commerce, +12 si el sitio está caído,
-- +8 si no tiene carrito. Llenar los campos sin recalcular habría dejado a
-- todas en 18 — un puntaje que se calculó una vez al sembrar es un puntaje
-- que miente. Misma fórmula, mismos topes.
update abm_cuentas set
  dolor = least(50,
    (case when plataforma_web ~* 'shopify|woo|vtex|wix|tiendanube|magento|prestashop|squarespace|shopline'
           and (coalesce(sucursales,0) >= 2 or sucursales is null) then 16 else 0 end)
  + (case when sitio_http = 0 or sitio_http >= 400 then 12 else 0 end)
  + (case when sitio_carrito = false then 8 else 0 end))
where giro in ('calzado','mayoristas') and sitio_http is not null;

update abm_cuentas set puntaje = least(100, coalesce(encaje,0) + coalesce(dolor,0))
where giro in ('calzado','mayoristas');
